/**
 * Generates `supabase/schema.sql` from `src/data/quotes.seed.js`.
 *
 * Run with:  npm run seed
 *
 * The generated file is what you paste into Supabase → SQL Editor → Run.
 * It is idempotent: tables/policies/triggers are (re)created safely, and the
 * quote seed only inserts when the table is empty.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { seedQuotes } from "../src/data/quotes.seed.js";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");

const esc = (value) => value.replaceAll("'", "''");

const values = seedQuotes
  .map(
    (quote, index) =>
      `  ('${esc(quote.en)}', '${esc(quote.id)}', '{${quote.tags.join(",")}}')${index === seedQuotes.length - 1 ? "" : ","}`,
  )
  .join("\n");

const sql = `-- ============================================================================
-- Stay Here — Supabase schema + seed
--
-- How to use:
--   1. Open your Supabase project → SQL Editor → New query.
--   2. Paste this entire file and press Run.
--
-- Safe to re-run: the schema is idempotent and the quote seed only inserts
-- when the table is still empty.
--
-- This file is generated by scripts/generate-seed.mjs from
-- src/data/quotes.seed.js — edit the data file and run \`npm run seed\`
-- instead of editing here.
-- ============================================================================

create extension if not exists pgcrypto;

-- ----------------------------------------------------------------------------
-- Table
-- ----------------------------------------------------------------------------
create table if not exists public.quotes (
  id uuid primary key default gen_random_uuid(),
  text_en text not null check (length(trim(text_en)) > 0),
  text_id text,
  author text,
  tags text[] not null default '{}',
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists quotes_published_idx on public.quotes (published);

-- ----------------------------------------------------------------------------
-- updated_at trigger
-- ----------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists quotes_touch_updated_at on public.quotes;
create trigger quotes_touch_updated_at
  before update on public.quotes
  for each row
  execute function public.touch_updated_at();

-- ----------------------------------------------------------------------------
-- Row Level Security
--   * anonymous visitors read published quotes only
--   * any signed-in user (your admin account) has full write access
-- ----------------------------------------------------------------------------
alter table public.quotes enable row level security;

drop policy if exists "quotes: public reads published" on public.quotes;
create policy "quotes: public reads published"
  on public.quotes
  for select
  using (published = true);

drop policy if exists "quotes: admin reads all" on public.quotes;
create policy "quotes: admin reads all"
  on public.quotes
  for select
  to authenticated
  using (true);

drop policy if exists "quotes: admin inserts" on public.quotes;
create policy "quotes: admin inserts"
  on public.quotes
  for insert
  to authenticated
  with check (true);

drop policy if exists "quotes: admin updates" on public.quotes;
create policy "quotes: admin updates"
  on public.quotes
  for update
  to authenticated
  using (true)
  with check (true);

drop policy if exists "quotes: admin deletes" on public.quotes;
create policy "quotes: admin deletes"
  on public.quotes
  for delete
  to authenticated
  using (true);

-- ----------------------------------------------------------------------------
-- Privileges
--   Supabase grants these via default privileges already; stating them
--   explicitly keeps this file self-contained everywhere else too.
--   Row visibility is still decided by the RLS policies above.
-- ----------------------------------------------------------------------------
grant usage on schema public to anon, authenticated;
grant select on table public.quotes to anon;
grant select, insert, update, delete on table public.quotes to authenticated;

-- ----------------------------------------------------------------------------
-- Seed — only runs when the table is empty
-- ----------------------------------------------------------------------------
insert into public.quotes (text_en, text_id, tags)
select text_en, text_id, tags::text[]
from (
  values
${values}
) as seed(text_en, text_id, tags)
where not exists (select 1 from public.quotes);
`;

const target = join(root, "supabase", "schema.sql");
mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, sql);

console.log(`Wrote ${target} (${seedQuotes.length} quotes).`);
